class Solution {
  public long elevatorRequests(int n, int start, int[] requests) {
    int m = requests.length;
    int[] r = requests.clone();
    java.util.Arrays.sort(r);
    long INF = Long.MAX_VALUE / 4;
    long[][][] dp = new long[m][m][2];
    for (long[][] a : dp) for (long[] b : a) java.util.Arrays.fill(b, INF);
    int idx = -1;
    for (int i = 0; i < m; i++) if (r[i] == start) idx = i;
    if (idx >= 0) {
      dp[idx][idx][0] = dp[idx][idx][1] = 0;
    } else {
      int a = -1, b = -1;
      for (int i = 0; i < m; i++) {
        if (r[i] < start) a = i;
        else if (b < 0) b = i;
      }
      if (a >= 0) dp[a][a][0] = dp[a][a][1] = (long) (start - r[a]) * m;
      if (b >= 0) dp[b][b][0] = dp[b][b][1] = (long) (r[b] - start) * m;
    }
    for (int len = 1; len < m; len++) {
      for (int i = 0; i + len - 1 < m; i++) {
        int j = i + len - 1;
        int remaining = m - len;
        for (int side = 0; side < 2; side++) {
          long cur = dp[i][j][side];
          if (cur >= INF) continue;
          int pos = side == 0 ? r[i] : r[j];
          if (i > 0) {
            long cost = cur + (long) (pos - r[i - 1]) * remaining;
            if (cost < dp[i - 1][j][0]) dp[i - 1][j][0] = cost;
          }
          if (j + 1 < m) {
            long cost = cur + (long) (r[j + 1] - pos) * remaining;
            if (cost < dp[i][j + 1][1]) dp[i][j + 1][1] = cost;
          }
        }
      }
    }
    return Math.min(dp[0][m - 1][0], dp[0][m - 1][1]);
  }
}
